/**
 * Service-worker registration for the POS PWA.
 *
 * The SW itself (generated by vite-plugin-pwa / Workbox) precaches the app
 * shell and only serves offline navigations for the `/sales/pos` route — the
 * rest of the app still needs the network. See vite.config.js.
 *
 * We register with `registerType: 'prompt'`, so a freshly deployed build does
 * NOT auto-activate mid-shift; instead `onNeedRefresh` fires and the UI asks
 * the cashier to reload when it's safe.
 */

import { ref } from 'vue'

// Reactive flags any component can watch (the POS top bar uses these).
export const needsRefresh = ref(false)
export const offlineReady = ref(false)

let updateServiceWorker = null

export async function initPwa() {
  // No SW in dev (vite-plugin-pwa devOptions.enabled = false) — the virtual
  // module still resolves, but registration is a no-op there.
  if (import.meta.env.DEV) return

  try {
    const { registerSW } = await import('virtual:pwa-register')

    updateServiceWorker = registerSW({
      immediate: true,
      onNeedRefresh() {
        needsRefresh.value = true
      },
      onOfflineReady() {
        offlineReady.value = true
      },
      onRegisteredSW(swUrl, registration) {
        // Re-check for a new build every 30 min while the app stays open
        // (a till PWA can run for days without a reload).
        if (registration) {
          setInterval(() => registration.update(), 30 * 60 * 1000)
        }
      },
    })
  } catch (err) {
    // A missing/broken SW must never take the app down.
    console.warn('[pwa] service worker registration skipped:', err)
  }
}

/** Called from the "New version — reload" prompt. Activates the new SW and reloads. */
export function applyUpdate() {
  needsRefresh.value = false
  if (updateServiceWorker) updateServiceWorker(true)
  else window.location.reload()
}
